package store

var nodePairTrustSchemaObjects = append([]string{
	"hub_node_pair_trust_v1", "hub_node_pair_trust_v1_candidate", "hub_node_pair_trust_v1_live_node", "hub_node_pair_trust_receipts_v1", "hub_node_pair_trust_slots_v1", "hub_node_pair_trust_slots_v1_current",
	"hub_node_pair_trust_v1_no_delete", "hub_node_pair_trust_v1_coordinates", "hub_node_pair_trust_receipts_v1_no_delete", "hub_node_pair_trust_receipts_v1_no_update", "hub_node_pair_trust_slots_v1_no_delete", "hub_node_pair_trust_slots_v1_coordinates", "hub_node_pair_trust_counter_guard_v1",
	"node_control_pair_trust_required_v1",
}, nodePairTrustBudgetObjects...)

func (s *Store) initializeHubNodePairTrustSchema() error {
	_, err := s.db.Exec(`
ALTER TABLE node_control_key_requests_v1 ADD COLUMN require_pair_trust_ack INTEGER NOT NULL DEFAULT 0 CHECK(require_pair_trust_ack IN(0,1));
CREATE TRIGGER node_control_pair_trust_required_v1 BEFORE UPDATE OF require_pair_trust_ack ON node_control_key_requests_v1 WHEN OLD.require_pair_trust_ack=1 AND NEW.require_pair_trust_ack!=1 BEGIN SELECT RAISE(ABORT,'Node pairing ACK provenance cannot be cleared');END;
CREATE TABLE hub_node_pair_trust_v1(attempt_id TEXT PRIMARY KEY,node_id TEXT NOT NULL,node_key_id TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN('INITIAL_CANDIDATE','EXISTING_BINDING')),candidate_request_id TEXT NOT NULL,context_digest TEXT NOT NULL CHECK(length(context_digest)=64),context_json TEXT NOT NULL,authorized INTEGER NOT NULL DEFAULT 0 CHECK(authorized IN(0,1)),reserved_bytes INTEGER NOT NULL DEFAULT 0 CHECK(reserved_bytes>=0),gc_after TEXT NOT NULL,oob_commitment TEXT NOT NULL DEFAULT '',state TEXT NOT NULL CHECK(state IN('PENDING','OWNER_APPROVED','ACKING','ACKED','EXPIRED','CANCELLED','REVOKED','FENCED')),record_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX hub_node_pair_trust_v1_candidate ON hub_node_pair_trust_v1(candidate_request_id) WHERE candidate_request_id!='';
CREATE UNIQUE INDEX hub_node_pair_trust_v1_live_node ON hub_node_pair_trust_v1(node_id) WHERE state IN('PENDING','OWNER_APPROVED','ACKING');
CREATE TABLE hub_node_pair_trust_receipts_v1(sender_key_id TEXT NOT NULL,request_id TEXT NOT NULL,attempt_id TEXT NOT NULL,operation TEXT NOT NULL,request_digest TEXT NOT NULL CHECK(length(request_digest)=64),state TEXT NOT NULL,response_packet BLOB NOT NULL CHECK(length(response_packet)>0 AND length(response_packet)<=3145728),created_at TEXT NOT NULL,PRIMARY KEY(sender_key_id,request_id));
CREATE TABLE hub_node_pair_trust_slots_v1(attempt_id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,device_id TEXT NOT NULL,session_epoch INTEGER NOT NULL,request_sequence INTEGER NOT NULL,response_sequence INTEGER NOT NULL,operation_id TEXT NOT NULL,packet_digest TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('RESERVED','DONE')),created_at TEXT NOT NULL);
CREATE UNIQUE INDEX hub_node_pair_trust_slots_v1_current ON hub_node_pair_trust_slots_v1(owner_id,device_id) WHERE state='RESERVED';
CREATE TRIGGER hub_node_pair_trust_v1_no_delete BEFORE DELETE ON hub_node_pair_trust_v1 WHEN OLD.authorized=1 OR OLD.state NOT IN('EXPIRED','CANCELLED','FENCED') BEGIN SELECT RAISE(ABORT,'Node pairing trust history is permanent');END;
CREATE TRIGGER hub_node_pair_trust_v1_coordinates BEFORE UPDATE ON hub_node_pair_trust_v1 WHEN NEW.attempt_id!=OLD.attempt_id OR NEW.node_id!=OLD.node_id OR NEW.node_key_id!=OLD.node_key_id OR NEW.mode!=OLD.mode OR NEW.candidate_request_id!=OLD.candidate_request_id OR NEW.context_digest!=OLD.context_digest OR NEW.context_json!=OLD.context_json OR NEW.created_at!=OLD.created_at OR NEW.gc_after!=OLD.gc_after OR NEW.authorized<OLD.authorized OR (OLD.oob_commitment!='' AND NEW.oob_commitment!=OLD.oob_commitment) OR (OLD.state IN('ACKED','EXPIRED','CANCELLED','REVOKED','FENCED') AND (NEW.state!=OLD.state OR NEW.record_json!=OLD.record_json OR NEW.oob_commitment!=OLD.oob_commitment)) BEGIN SELECT RAISE(ABORT,'Node pairing trust coordinates and terminal history are immutable');END;
CREATE TRIGGER hub_node_pair_trust_receipts_v1_no_delete BEFORE DELETE ON hub_node_pair_trust_receipts_v1 BEGIN SELECT RAISE(ABORT,'Node pairing receipts are permanent');END;
CREATE TRIGGER hub_node_pair_trust_receipts_v1_no_update BEFORE UPDATE ON hub_node_pair_trust_receipts_v1 BEGIN SELECT RAISE(ABORT,'Node pairing original receipt is immutable');END;
CREATE TRIGGER hub_node_pair_trust_slots_v1_no_delete BEFORE DELETE ON hub_node_pair_trust_slots_v1 BEGIN SELECT RAISE(ABORT,'Node pairing Client slot history is permanent');END;
CREATE TRIGGER hub_node_pair_trust_slots_v1_coordinates BEFORE UPDATE ON hub_node_pair_trust_slots_v1 WHEN NEW.attempt_id!=OLD.attempt_id OR NEW.owner_id!=OLD.owner_id OR NEW.device_id!=OLD.device_id OR NEW.session_epoch!=OLD.session_epoch OR NEW.request_sequence!=OLD.request_sequence OR NEW.response_sequence!=OLD.response_sequence OR NEW.operation_id!=OLD.operation_id OR NEW.packet_digest!=OLD.packet_digest OR NEW.created_at!=OLD.created_at OR (OLD.state='DONE' AND NEW.state!='DONE') BEGIN SELECT RAISE(ABORT,'Node pairing original Client slot cannot move');END;
CREATE TRIGGER hub_node_pair_trust_counter_guard_v1 BEFORE UPDATE OF last_request_sequence,next_response_sequence ON client_devices_v2 WHEN NEW.session_epoch=OLD.session_epoch AND (NEW.last_request_sequence!=OLD.last_request_sequence OR NEW.next_response_sequence!=OLD.next_response_sequence) AND EXISTS(SELECT 1 FROM hub_node_pair_trust_slots_v1 slot JOIN hub_node_pair_trust_v1 attempt ON attempt.attempt_id=slot.attempt_id WHERE slot.owner_id=OLD.owner_id AND slot.device_id=OLD.device_id AND slot.session_epoch=OLD.session_epoch AND slot.state='RESERVED' AND NOT(attempt.state='ACKING' AND OLD.last_request_sequence=slot.request_sequence-1 AND NEW.last_request_sequence=slot.request_sequence AND OLD.next_response_sequence=slot.response_sequence AND NEW.next_response_sequence=slot.response_sequence+1)) BEGIN SELECT RAISE(ABORT,'Node pairing ACK required before original Client counter settlement');END;
` + nodePairTrustBudgetSQL)
	return err
}
